"""OCR accuracy on the 20-document test set (FR-062 / AL-249).

    python backend/tests/fixtures/ocr/evaluate.py   # first run downloads Florence-2-base (~0.5 GB)

Extracts images with the parser's layout mode, runs the real OCR model (Florence-2-base,
in-process), compares with ground_truth.json and writes docs/OCR_ACCURACY.md.
Character accuracy = 1 - edit distance / length of the ground truth, after lower-casing
and collapsing whitespace (so layout spacing does not count as an error).
"""
from __future__ import annotations

import base64
import importlib.util
import json
import re
import sys
import time
from pathlib import Path

HERE = Path(__file__).parent
REPO = HERE.parents[3]
TARGETS = {"clean": 0.90, "low": 0.70}  # FR-062 acceptance criteria


def _load(name: str, path: Path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def normalise(text: str) -> str:
    return re.sub(r"\s+", " ", text.lower()).strip()


def edit_distance(a: str, b: str) -> int:
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i]
        for j, cb in enumerate(b, 1):
            current.append(min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + (ca != cb)))
        previous = current
    return previous[-1]


def char_accuracy(predicted: str, truth: str) -> float:
    p, t = normalise(predicted), normalise(truth)
    return max(0.0, 1 - edit_distance(p, t) / max(1, len(t)))


def main() -> int:
    runner = _load("parser_runner", REPO / "docker" / "parser" / "runner.py")
    engines = _load("ocr_engines", REPO / "backend" / "app" / "services" / "ocr_engines.py")
    service = engines.OCRService()
    truth = json.loads((HERE / "ground_truth.json").read_text(encoding="utf-8"))

    rows, per_doc = [], []
    started = time.perf_counter()
    for name, expected in truth.items():
        layout = runner.extract_layout(HERE / "testset" / name)
        payloads = [base64.b64decode(img["data"]) for img in layout["images"]]
        t0 = time.perf_counter()
        results = service.recognize(payloads, timeout_seconds=120)
        seconds = time.perf_counter() - t0
        scores = []
        for item in expected:
            result = results[item["image_index"]] if item["image_index"] < len(results) else None
            text = result.text if result and not result.error else ""
            score = char_accuracy(text, item["text"])
            scores.append(score)
            rows.append((name, item["image_index"] + 1, item["quality"], item["text"], text,
                         result.engine if result else "-", result.confidence if result else 0.0, score))
        per_doc.append((name, expected[0]["quality"], len(expected), sum(scores) / len(scores), seconds))
        print(f"{name}: {per_doc[-1][3]:.1%} in {seconds:.1f}s")

    summary = {}
    for quality in ("clean", "low"):
        scores = [r[7] for r in rows if r[2] == quality]
        summary[quality] = sum(scores) / len(scores)
    total = time.perf_counter() - started
    engine_used = sorted({r[5] for r in rows})

    lines = [
        "# OCR Accuracy Report (FR-062)",
        "",
        "Generated by `backend/tests/fixtures/ocr/evaluate.py` on the 20-document test set in "
        "`backend/tests/fixtures/ocr/` (10 PDF + 10 DOCX, synthetic text, no personal data).",
        "",
        "Character accuracy = 1 − edit distance / ground-truth length, case-insensitive with "
        "whitespace collapsed. \"Low\" images are degraded on purpose: smaller grey text, ±2.5° "
        "rotation, blur, salt noise and JPEG quality 25.",
        "",
        "## Summary",
        "",
        "| Image quality | Images | Mean character accuracy | Target | Result |",
        "|---|---|---|---|---|",
    ]
    for quality in ("clean", "low"):
        count = sum(1 for r in rows if r[2] == quality)
        ok = "met" if summary[quality] >= TARGETS[quality] else "NOT met"
        lines.append(f"| {quality} | {count} | {summary[quality]:.1%} | ≥ {TARGETS[quality]:.0%} | {ok} |")
    lines += [
        "",
        f"OCR engine(s) used: {', '.join(engine_used)}. CPU only. Total OCR time {total:.0f} s for "
        f"{len(rows)} images ({total / len(per_doc):.1f} s per document; budget 30 s per document).",
        "",
        "## Per document",
        "",
        "| Document | Quality | Images | Accuracy | OCR time (s) |",
        "|---|---|---|---|---|",
    ]
    lines += [f"| {n} | {q} | {c} | {a:.1%} | {s:.1f} |" for n, q, c, a, s in per_doc]
    lines += [
        "",
        "## Limitations",
        "",
        "- The test images are single printed lines in a standard font. Real scans (handwriting, "
        "multi-column pages, tables, stamps, heavy skew or low resolution) will score lower; add such "
        "samples to the test set when real, non-confidential documents are available.",
        "- The degradations used for \"low\" images did not reduce Florence-2's accuracy much, so the "
        "low-quality set is easier than real poor scans and should be made harder.",
        "- The first document includes model loading time; later documents show the steady-state speed.",
    ]
    lines += ["", "## Per image", "", "| Document | Image | Expected | OCR output | Confidence | Accuracy |",
              "|---|---|---|---|---|---|"]
    lines += [f"| {n} | {i} | {e} | {o.replace('|', '/')} | {c:.2f} | {a:.1%} |" for n, i, _, e, o, _, c, a in rows]
    out = REPO / "docs" / "OCR_ACCURACY.md"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"clean {summary['clean']:.1%}, low {summary['low']:.1%} -> {out}")
    return 0 if all(summary[q] >= TARGETS[q] for q in TARGETS) else 1


if __name__ == "__main__":
    sys.exit(main())
